macro_rules! d_AccountSettings_c3d2ce7b {
    () => {
        "\"AccountSettings\":{\"description\":\"Per-model account settings, discriminated by `model`: every branch is an object whose `model` member is a `const`, which is what lets each generated binding emit a tagged union, so an unusable setting is answered as `external:invalidSettings` naming the member rather than as an unparseable payload. Never a secret: every value here is returned to anyone who may read the account. Branches are referred to by their `model` (\\\"the `sui-signer` settings\\\"). They carry no `title`, so that every binding renders each as a plain variant of this union.\",\"oneOf\":[{\"additionalProperties\":false,\"description\":\"Egress: `rolesanywhere.<region>.amazonaws.com`, plus `sts.<region>.amazonaws.com` when `chainedRoleArn` is set.\",\"properties\":{\"bucket\":{\"$ref\":\"#/$defs/ProviderBucketName\",\"description\":\"The S3 bucket issuances are scoped within. Required for an account whose bindings issue storage scopes.\"},\"chainedRoleArn\":{\"$ref\":\"#/$defs/AwsArn\",\"description\":\"When set, every issuance chains an AssumeRole into this role carrying the downscoping session policy, for deployments whose Roles Anywhere profile cannot carry one per request. Caps a credential at one hour.\"},\"model\":{\"const\":\"aws-roles-anywhere\",\"type\":\"string\"},\"probePrefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\",\"description\":\"Where external/accounts/probe writes its canary when no binding names a narrower prefix. Lets a new account be probed before anything is bound to it. Absent, a probe of an account with no bindings stops after `exchange` and reports `complete: false`.\"},\"profileArn\":{\"$ref\":\"#/$defs/AwsArn\"},\"region\":{\"$ref\":\"#/$defs/AwsRegion\"},\"roleArn\":{\"$ref\":\"#/$defs/AwsArn\"},\"trustAnchorArn\":{\"$ref\":\"#/$defs/AwsArn\",\"description\":\"The trust anchor holding the custodian's CA certificate. Recorded after the administrator creates it from external/accounts/setup.\"}},\"required\":[\"model\",\"region\",\"profileArn\",\"roleArn\",\"trustAnchorArn\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: `sts.googleapis.com`, plus `iamcredentials.googleapis.com` when `serviceAccount` is set.\",\"properties\":{\"bucket\":{\"$ref\":\"#/$defs/ProviderBucketName\",\"description\":\"The GCS bucket issuances are scoped within, by a Credential Access Boundary.\"},\"model\":{\"const\":\"gcp-wif-pinned\",\"type\":\"string\"},\"poolId\":{\"pattern\":\"^[a-z0-9-]{4,32}$\",\"type\":\"string\"},\"probePrefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\",\"description\":\"Where external/accounts/probe writes its canary when no binding names a narrower prefix. Lets a new account be probed before anything is bound to it. Absent, a probe of an account with no bindings stops after `exchange` and reports `complete: false`.\"},\"projectNumber\":{\"pattern\":\"^[0-9]{1,20}$\",\"type\":\"string\"},\"providerId\":{\"pattern\":\"^[a-z0-9-]{4,32}$\",\"type\":\"string\"},\"serviceAccount\":{\"description\":\"When set, the federated token is exchanged for this service account's access token.\",\"maxLength\":254,\"pattern\":\"^[a-z0-9-]+@[a-z0-9-]+\\\\.iam\\\\.gserviceaccount\\\\.com$\",\"type\":\"string\"},\"signingAlgorithm\":{\"description\":\"The ID-token algorithm. ES256 unless the provider refuses it. Absent means ES256.\",\"enum\":[\"ES256\",\"RS256\"],\"type\":\"string\"}},\"required\":[\"model\",\"projectNumber\",\"poolId\",\"providerId\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: `login.microsoftonline.com`, or the sovereign-cloud authority named in `authorityHost`.\",\"properties\":{\"authorityHost\":{\"description\":\"Absent means `login.microsoftonline.com`.\",\"maxLength\":253,\"pattern\":\"^[a-z0-9.-]+$\",\"type\":\"string\"},\"clientId\":{\"pattern\":\"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"type\":\"string\"},\"model\":{\"const\":\"azure-cert\",\"type\":\"string\"},\"tenantId\":{\"pattern\":\"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"type\":\"string\"},\"tokenScope\":{\"description\":\"The `scope` requested at the token endpoint, such as `https://storage.azure.com/.default`.\",\"maxLength\":512,\"pattern\":\"^[A-Za-z0-9:/._-]+$\",\"type\":\"string\"}},\"required\":[\"model\",\"tenantId\",\"clientId\",\"tokenScope\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: the host of `tokenEndpoint`, and nothing else.\",\"properties\":{\"audience\":{\"description\":\"The assertion's `aud`. Absent means `tokenEndpoint`.\",\"maxLength\":2048,\"pattern\":\"^[!-~]+$\",\"type\":\"string\"},\"clientId\":{\"maxLength\":512,\"minLength\":1,\"pattern\":\"^[!-~]+$\",\"type\":\"string\"},\"model\":{\"const\":\"oauth2-private-key-jwt\",\"type\":\"string\"},\"scopes\":{\"description\":\"The scopes a binding may request, the ceiling for every issuance.\",\"items\":{\"maxLength\":256,\"pattern\":\"^[!#-\\\\[\\\\]-~]+$\",\"type\":\"string\"},\"maxItems\":64,\"type\":\"array\",\"uniqueItems\":true},\"signingAlgorithm\":{\"enum\":[\"ES256\",\"RS256\"],\"type\":\"string\"},\"tokenEndpoint\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"}},\"required\":[\"model\",\"tokenEndpoint\",\"clientId\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Issuance needs no egress: presigning is a computation inside the custodian, and the consumer uses the URL itself. The probe connects to the host of `endpoint`, which `egressHosts` therefore lists.\",\"properties\":{\"accessKeyId\":{\"description\":\"The access key's identifier. Not a secret: it appears in every presigned URL. The secret half is set with external/accounts/secret/set and never returned.\",\"maxLength\":128,\"pattern\":\"^[A-Za-z0-9]+$\",\"type\":\"string\"},\"bucket\":{\"$ref\":\"#/$defs/ProviderBucketName\"},\"endpoint\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"},\"model\":{\"const\":\"s3-static-presign\",\"type\":\"string\"},\"pathStyle\":{\"description\":\"Address the bucket in the path rather than the host name, as MinIO usually needs.\",\"type\":\"boolean\"},\"probePrefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\",\"description\":\"Where external/accounts/probe writes its canary when no binding names a narrower prefix. Lets a new account be probed before anything is bound to it. Absent, a probe of an account with no bindings stops after `exchange` and reports `complete: false`.\"},\"region\":{\"description\":\"The SigV4 signing region; `auto` for Cloudflare R2.\",\"maxLength\":64,\"pattern\":\"^[a-z0-9-]+$\",\"type\":\"string\"}},\"required\":[\"model\",\"endpoint\",\"region\",\"bucket\",\"accessKeyId\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"No egress: the custodian signs and the consumer submits the transaction. The allow-list, the gas caps and the coin caps are the account's whole authority; a transaction outside them is refused before anything is signed.\",\"properties\":{\"allowedCalls\":{\"description\":\"Every MoveCall command in a signed transaction must name one of these. For Walrus storage: the system package's `register_blob`, `certify_blob`, `extend_blob` and `delete_blob`, and the coin calls needed to pay for them.\",\"items\":{\"$ref\":\"#/$defs/SuiMoveCall\"},\"maxItems\":32,\"minItems\":1,\"type\":\"array\"},\"allowedObjects\":{\"description\":\"Shared objects a transaction may take as input, such as the Walrus system and staking objects. Absent means any object the allowed calls accept.\",\"items\":{\"pattern\":\"^0x[0-9a-f]{64}$\",\"type\":\"string\"},\"maxItems\":32,\"type\":\"array\"},\"maxCoinOutPerTx\":{\"description\":\"Per coin type, the most a single transaction may spend or transfer out of the account's address, in the coin's smallest unit. A coin type not listed may not leave the address at all.\",\"items\":{\"additionalProperties\":false,\"properties\":{\"amount\":{\"minimum\":0,\"type\":\"integer\"},\"coinType\":{\"maxLength\":512,\"pattern\":\"^0x[0-9a-f]{1,64}::[A-Za-z0-9_]+::[A-Za-z0-9_]+$\",\"type\":\"string\"}},\"required\":[\"coinType\",\"amount\"],\"type\":\"object\"},\"maxItems\":8,\"type\":\"array\"},\"maxGasBudgetMist\":{\"description\":\"The largest gas budget one transaction may declare.\",\"minimum\":1,\"type\":\"integer\"},\"maxGasPerDayMist\":{\"description\":\"The total gas budget signed per rolling 24 hours.\",\"minimum\":1,\"type\":\"integer\"},\"model\":{\"const\":\"sui-signer\",\"type\":\"string\"},\"network\":{\"enum\":[\"mainnet\",\"testnet\",\"devnet\"],\"type\":\"string\"}},\"required\":[\"model\",\"network\",\"allowedCalls\",\"maxGasBudgetMist\",\"maxGasPerDayMist\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: the host of `baseUrl`. The secret is set with external/accounts/secret/set and used only inside the custodian by `driver`; a provider reachable only by handing the consumer the raw key is not supported.\",\"properties\":{\"baseUrl\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"},\"driver\":{\"description\":\"The custodian's driver that uses the secret: performs a login or token exchange and returns a short-lived result. A custodian refuses a driver it does not implement.\",\"maxLength\":64,\"pattern\":\"^[a-z0-9][a-z0-9-]*$\",\"type\":\"string\"},\"model\":{\"const\":\"static-secret\",\"type\":\"string\"}},\"required\":[\"model\",\"driver\",\"baseUrl\"],\"type\":\"object\"}],\"title\":\"AccountSettings\"}"
    };
}
pub(crate) use d_AccountSettings_c3d2ce7b;

macro_rules! d_AccountSetupArtifacts_023fd3a1 {
    () => {
        "\"AccountSetupArtifacts\":{\"additionalProperties\":false,\"description\":\"What an administrator does at the provider to make an account usable, generated by the custodian from the account's settings, public material and bindings. Public material and policy only: never a private key or secret, and the custodian never asks for the provider's administrator credentials.\",\"properties\":{\"artifacts\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"content\":{\"maxLength\":65536,\"type\":\"string\"},\"mediaType\":{\"maxLength\":128,\"pattern\":\"^[a-z]+/[a-z0-9.+-]+$\",\"type\":\"string\"},\"name\":{\"description\":\"File name to save it under: `trust-anchor.pem`, `jwks.json`, `permissions-policy.json`, `crl.pem`.\",\"maxLength\":128,\"pattern\":\"^[A-Za-z0-9._-]+$\",\"type\":\"string\"}},\"required\":[\"name\",\"mediaType\",\"content\"],\"type\":\"object\"},\"maxItems\":16,\"type\":\"array\"},\"model\":{\"$ref\":\"#/$defs/AuthModel\"},\"steps\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"command\":{\"description\":\"A provider CLI command (`aws rolesanywhere create-trust-anchor …`, `gcloud iam workload-identity-pools providers create-oidc … --jwk-json-path`, `az ad app credential reset --cert …`), referring to artifacts by `name`.\",\"maxLength\":8192,\"type\":\"string\"},\"description\":{\"maxLength\":1024,\"type\":\"string\"}},\"required\":[\"description\"],\"type\":\"object\"},\"maxItems\":32,\"type\":\"array\"}},\"required\":[\"model\",\"artifacts\",\"steps\"],\"title\":\"AccountSetupArtifacts\",\"type\":\"object\"}"
    };
}
pub(crate) use d_AccountSetupArtifacts_023fd3a1;

