macro_rules! d_Account_05f1d26d {
    () => {
        "\"Account\":{\"additionalProperties\":false,\"description\":\"The mediator's view of one served account.\",\"properties\":{\"accessListCount\":{\"description\":\"Number of entries in the account's access list.\",\"minimum\":0,\"type\":\"integer\"},\"accountType\":{\"$ref\":\"#/$defs/AccountType\"},\"acl\":{\"$ref\":\"#/$defs/MediatorAcl\"},\"did\":{\"$ref\":\"#/$defs/Vid\",\"description\":\"The account's controlling DID, or — for privacy, and for mediators that key accounts by a one-way hash and never hold the full DID — a stable hash of that DID (see `Vid`). Whichever form is used, it is the opaque account identifier the other `account/*`, `acl/*`, and `access-list/*` tasks accept.\"},\"lastAuthenticatedAt\":{\"description\":\"The instant at which this account last completed authentication with the mediator, over any transport. Present only when the request set `includeActivity` and the mediator has recorded an authentication.\",\"format\":\"date-time\",\"type\":\"string\"},\"lastReceivedAt\":{\"description\":\"The instant at which the mediator last accepted a message addressed to this account. Present only when the request set `includeActivity` and the mediator has recorded such a message; MAY lag the true time by up to 60 seconds.\",\"format\":\"date-time\",\"type\":\"string\"},\"queueLimits\":{\"$ref\":\"#/$defs/QueueLimits\"},\"receiveQueueBytes\":{\"description\":\"Current byte size of queued receive messages.\",\"minimum\":0,\"type\":\"integer\"},\"receiveQueueCount\":{\"description\":\"Current count of queued receive messages.\",\"minimum\":0,\"type\":\"integer\"},\"sendQueueBytes\":{\"description\":\"Current byte size of queued send messages.\",\"minimum\":0,\"type\":\"integer\"},\"sendQueueCount\":{\"description\":\"Current count of queued send messages.\",\"minimum\":0,\"type\":\"integer\"},\"stats\":{\"$ref\":\"#/$defs/AccountStats\",\"description\":\"Lifetime counters the mediator keeps for this account. Present only when the request set `includeStats`.\"}},\"required\":[\"did\",\"accountType\",\"acl\"],\"title\":\"Account\",\"type\":\"object\"}"
    };
}
pub(crate) use d_Account_05f1d26d;

