macro_rules! d_AuthorityScopeContexts_132678ed {
    () => {
        "\"AuthorityScopeContexts\":{\"additionalProperties\":false,\"description\":\"The named contexts and, where the maintainer's contexts are hierarchical, every descendant of them — and nowhere else. `contexts` MUST carry at least one path.\",\"properties\":{\"contexts\":{\"description\":\"Non-empty set of context paths. An empty array is invalid (it is neither `all` nor `none`).\",\"items\":{\"$ref\":\"#/$defs/ContextPath\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"scope\":{\"const\":\"contexts\"}},\"required\":[\"scope\",\"contexts\"],\"title\":\"AuthorityScopeContexts\",\"type\":\"object\"}"
    };
}
pub(crate) use d_AuthorityScopeContexts_132678ed;

macro_rules! d_AuthorityScopeNone_608a8930 {
    () => {
        "\"AuthorityScopeNone\":{\"additionalProperties\":false,\"description\":\"No authority on this axis. Stated, not implied: `none` is how an entry says it may not act (a least-privilege approver) or may not approve.\",\"properties\":{\"scope\":{\"const\":\"none\"}},\"required\":[\"scope\"],\"title\":\"AuthorityScopeNone\",\"type\":\"object\"}"
    };
}
pub(crate) use d_AuthorityScopeNone_608a8930;

macro_rules! d_AuthorityScope_3c068034 {
    () => {
        "\"AuthorityScope\":{\"description\":\"An explicit authority scope — used for both the act scope and the approve scope of an entry. Exactly one of three shapes, discriminated by `scope`: `all`, `none`, or `contexts` with a NON-EMPTY list. The empty list is not a fourth shape: it is invalid, so a serializer that drops or empties the list produces a document that fails validation rather than one that silently means something else.\",\"oneOf\":[{\"$ref\":\"#/$defs/AuthorityScopeAll\"},{\"$ref\":\"#/$defs/AuthorityScopeNone\"},{\"$ref\":\"#/$defs/AuthorityScopeContexts\"}],\"title\":\"AuthorityScope\"}"
    };
}
pub(crate) use d_AuthorityScope_3c068034;

