macro_rules! d_BootstrapRequest_cd94d18a {
    () => {
        "\"BootstrapRequest\":{\"$anchor\":\"bootstrap-request\",\"additionalProperties\":false,\"description\":\"W3C Verifiable Presentation 2.0 (§6.1: VPs MAY omit `verifiableCredential`). Custom members `nonce`, `validUntil`, `label`, and `ask` sit alongside the standard VP fields and are covered by the same DataIntegrityProof.\",\"properties\":{\"@context\":{\"description\":\"JSON-LD contexts. MUST contain both `https://www.w3.org/ns/credentials/v2` and `https://openvtc.org/contexts/bootstrap-v1`. Maintainers verifying the proof MAY refuse other shapes.\",\"items\":{\"format\":\"uri\",\"type\":\"string\"},\"minItems\":2,\"type\":\"array\"},\"ask\":{\"$ref\":\"#/$defs/BootstrapAsk\",\"description\":\"What the holder is asking the maintainer to do. Tagged on `type`; see `TemplateBootstrapAsk` and `AdminRotationAsk`.\"},\"holder\":{\"description\":\"The integration's ephemeral did:key (Ed25519). Identifies the party the returned bundle is HPKE-sealed for; the VP proof verifies under this DID's verification method.\",\"minLength\":1,\"pattern\":\"^did:key:z[1-9A-HJ-NP-Za-km-z]+$\",\"type\":\"string\"},\"id\":{\"description\":\"URN-shaped identifier for this presentation. `urn:uuid:<v4>` is RECOMMENDED.\",\"minLength\":1,\"type\":\"string\"},\"label\":{\"description\":\"Optional human-readable label carried into the maintainer's audit log.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"nonce\":{\"description\":\"16 random bytes encoded as base64url-no-pad (22 characters). The maintainer treats this as the sealed bundle's `bundleId` (decoded to hex, exposed in `summary.bundleIdHex`) and SHOULD enforce one-shot semantics — a second provisioning with the same nonce MUST be refused as a replay.\",\"pattern\":\"^[A-Za-z0-9_-]{22}$\",\"type\":\"string\"},\"proof\":{\"$ref\":\"#/$defs/DataIntegrityProof\",\"description\":\"Data Integrity proof signed by the holder's Ed25519 key. Cryptosuite MUST equal `eddsa-jcs-2022`. `proofPurpose` MUST equal `authentication`. `verificationMethod` MUST resolve under `holder`. Signs the JCS canonicalisation of the VP with `proof` removed.\"},\"type\":{\"description\":\"VP types. MUST contain both `VerifiablePresentation` and `BootstrapRequest`. Additional task-specific types MAY be present.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"minItems\":2,\"type\":\"array\"},\"validUntil\":{\"description\":\"Freshness bound for the VP. RFC 3339 UTC. Maintainers SHOULD allow ±5 minutes of clock skew.\",\"format\":\"date-time\",\"type\":\"string\"}},\"required\":[\"@context\",\"type\",\"id\",\"holder\",\"nonce\",\"validUntil\",\"ask\",\"proof\"],\"title\":\"BootstrapRequest\",\"type\":\"object\"}"
    };
}
