macro_rules! d_CapabilityGrant_b7831816 {
    () => {
        "\"CapabilityGrant\":{\"additionalProperties\":false,\"description\":\"A capability held by an entry, optionally qualified by a resource, optionally marked additive. A qualified grant confers nothing without a live entry for the same subject, and is bounded as delegated authority is.\",\"properties\":{\"additive\":{\"description\":\"`true` declares an ADDITIVE grant: a capability no role implies, granted to this entry beside its role rather than through it, and therefore not intersected with the role's ceiling. Granting one requires unrestricted act authority (`act: {scope: all}`) of the granter, and an entry never acquires one by virtue of its role. Absent or `false` → an ordinary grant, intersected with the role's ceiling, and refused when written if it lies outside it. A consumer MUST refuse `additive: true` on a capability the role's ceiling already includes, so that the flag cannot be used to make an ordinary capability survive a later role change.\",\"type\":\"boolean\"},\"capability\":{\"$ref\":\"#/$defs/Capability\"},\"resource\":{\"$ref\":\"#/$defs/ResourceQualifier\",\"description\":\"Optional qualifier. Absent covers every resource of the capability's kind.\"}},\"required\":[\"capability\"],\"title\":\"CapabilityGrant\",\"type\":\"object\"}"
    };
}
pub(crate) use d_CapabilityGrant_b7831816;

macro_rules! d_CapabilityManifest_f6e57a3b {
    () => {
        "\"CapabilityManifest\":{\"additionalProperties\":false,\"description\":\"The self-description of a pluggable community capability: the Trust Task families it serves, the trust-registry vocabulary it reads and writes, the roles that may operate it, the membership lifecycle hooks it consumes, and the external adapters that act on its decisions. The manifest is what governance approves, what discovery advertises, and what a management UX renders.\",\"properties\":{\"capability\":{\"description\":\"The capability's namespace slug, e.g. `git-trust`.\",\"pattern\":\"^[a-z0-9][a-z0-9-]*$\",\"type\":\"string\"},\"configSchema\":{\"description\":\"Spec slug of the JSON schema the per-community `config` document must validate against.\",\"type\":\"string\"},\"consentClass\":{\"additionalProperties\":{\"enum\":[\"normal\",\"elevated\",\"destructive\"],\"type\":\"string\"},\"description\":\"Map of capability operation to the consent class its execution requires under the host's delegated-execution policy.\",\"type\":\"object\"},\"description\":{\"description\":\"One-paragraph description for management surfaces.\",\"maxLength\":1024,\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"externalAdapters\":{\"description\":\"Out-of-stack components that consume this capability's trust decisions.\",\"items\":{\"additionalProperties\":false,\"properties\":{\"kind\":{\"description\":\"Adapter type, e.g. `github-action`, `webhook`.\",\"type\":\"string\"},\"ref\":{\"description\":\"Where the adapter lives, e.g. a repository path or URL.\",\"type\":\"string\"}},\"required\":[\"kind\",\"ref\"],\"type\":\"object\"},\"type\":\"array\"},\"lifecycleHooks\":{\"description\":\"Membership lifecycle events the capability consumes, e.g. `member.enrolled`, `member.revoked`, `role.changed`.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"roles\":{\"additionalProperties\":{\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"description\":\"Map of capability operation (e.g. `grant`, `view`) to the community roles allowed to perform it.\",\"type\":\"object\"},\"specs\":{\"description\":\"Trust Task spec slugs (or `<family>/*` globs) this capability serves when enabled.\",\"items\":{\"type\":\"string\"},\"minItems\":1,\"type\":\"array\"},\"title\":{\"description\":\"Human-readable capability name for management surfaces.\",\"maxLength\":256,\"type\":\"string\"},\"version\":{\"description\":\"Manifest/capability version, `MAJOR.MINOR`.\",\"pattern\":\"^[0-9]+\\\\.[0-9]+$\",\"type\":\"string\"},\"vocabulary\":{\"additionalProperties\":false,\"description\":\"The trust-registry tuple vocabulary this capability may read and write. A conforming host MUST reject writes by this capability whose `action` is not listed.\",\"properties\":{\"actions\":{\"description\":\"TRQP `action` values this capability owns, e.g. `git.commit.sign`.\",\"items\":{\"type\":\"string\"},\"minItems\":1,\"type\":\"array\"},\"resourcePattern\":{\"description\":\"Human-readable pattern of the `resource` values used, e.g. `<org>[/<repo>]`.\",\"type\":\"string\"}},\"required\":[\"actions\"],\"type\":\"object\"}},\"required\":[\"capability\",\"version\",\"specs\"],\"title\":\"CapabilityManifest\",\"type\":\"object\"}"
    };
}
pub(crate) use d_CapabilityManifest_f6e57a3b;

