macro_rules! d_ContactDocument_ed43dbda {
    () => {
        "\"ContactDocument\":{\"additionalProperties\":false,\"description\":\"What a peer disclosed, as received. Structurally the same claim set a holder composes and presents — a profile and a contact card are one schema seen from two sides — which is why a maintainer validates both with the same code and a consumer renders both with the same view.\",\"properties\":{\"cardVersion\":{\"description\":\"The publisher's own monotonic counter, if they supplied one. Advisory: it orders the publisher's revisions relative to each other and MUST NOT be trusted to order them against anything else.\",\"minimum\":1,\"type\":\"integer\"},\"claims\":{\"items\":{\"additionalProperties\":false,\"properties\":{\"provenance\":{\"$ref\":\"#/$defs/Provenance\",\"description\":\"As asserted by the publisher. A recipient MUST NOT treat a claimed credentialBacked provenance as verified — it is a statement about what the publisher says backs the claim, and verification is a separate act against the credential itself.\"},\"type\":{\"$ref\":\"#/$defs/ClaimType\"},\"value\":{},\"valueType\":{\"$ref\":\"#/$defs/ValueType\"}},\"required\":[\"type\",\"valueType\",\"value\"],\"type\":\"object\"},\"maxItems\":256,\"type\":\"array\"},\"publisher\":{\"description\":\"The DID that published the document, as it appeared. Normally a pairwise identifier, so it names the relationship rather than the person.\",\"maxLength\":2048,\"type\":\"string\"}},\"required\":[\"claims\"],\"title\":\"ContactDocument\",\"type\":\"object\"}"
    };
}
