macro_rules! d_DriftSelector_d9f7e671 {
    () => {
        "\"DriftSelector\":{\"additionalProperties\":false,\"description\":\"Which of the repository's outstanding drift items to resolve. Drift items carry no identifier of their own: they are recomputed by the bridge and replaced wholesale by every git-ns/bridge/event. An item is selected by its `type`, and for the three role types also by the account whose role differs, which is unique among a repository's outstanding items.\",\"properties\":{\"account\":{\"$ref\":\"#/$defs/ForgeAccount\",\"description\":\"The account whose role differs, as the drift item reports it. Required for `roleAdded`, `roleRemoved` and `roleChanged`, and absent for every other type. Matched by `forge` and `id`; `login` is display only.\"},\"observed\":{\"description\":\"The item's `observed` value as the caller last read it. When present, the item is selected only if the forge still shows exactly this, so a decision made about one state is never applied to another. Required for `adopt`.\",\"maxLength\":256,\"type\":\"string\"},\"type\":{\"$ref\":\"#/$defs/DriftType\"}},\"required\":[\"type\"],\"title\":\"DriftSelector\",\"type\":\"object\"}"
    };
}
