macro_rules! d_ForgeStatus_b9fc9b50 {
    () => {
        "\"ForgeStatus\":{\"additionalProperties\":false,\"description\":\"What the bridge serving the namespace last reported about its standing on the forge owner — its app, its installation and what the owner's plan allows. Display only: it changes no decision the VTC takes. Every member but `missingPermissions` is absent until the bridge reports it.\",\"properties\":{\"appName\":{\"description\":\"The app's display name.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"appRegistration\":{\"description\":\"Where the app's manifest registration stands, in the bridge's words (`registered`, `pending`).\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"appSlug\":{\"description\":\"The app's URL slug on the forge.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"bridgePostedCheck\":{\"description\":\"The bridge can post the verify-trust check itself, the fallback where no required workflow is available.\",\"type\":\"boolean\"},\"installationId\":{\"description\":\"The forge's identifier for its installation of the community's app (GitHub).\",\"maxLength\":64,\"minLength\":1,\"type\":\"string\"},\"missingPermissions\":{\"description\":\"Permissions the app needs and the installation has not granted, in the forge's vocabulary. Empty when none are missing, or none were reported.\",\"items\":{\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"maxItems\":256,\"type\":\"array\",\"uniqueItems\":true},\"orgRulesets\":{\"description\":\"Organisation rulesets are available on the owner's plan.\",\"type\":\"boolean\"},\"permissionUpgradePending\":{\"description\":\"A new version of the app asks for permissions the forge owner has not approved yet.\",\"type\":\"boolean\"},\"reportedAt\":{\"description\":\"When the VTC received the report.\",\"format\":\"date-time\",\"type\":\"string\"},\"requiredWorkflow\":{\"description\":\"The organisation ruleset requiring the verify-trust workflow is in force.\",\"type\":\"boolean\"}},\"required\":[\"missingPermissions\"],\"title\":\"ForgeStatus\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ForgeStatus_b9fc9b50;

