macro_rules! d_KeyError_2da90e33 {
    () => {
        "\"KeyError\":{\"additionalProperties\":false,\"description\":\"Why one key of a batch read was not answered with a record: the code, and `details`, the key would have been refused with had it been read alone, carried in the shape a `trust-task-error` payload carries them.\",\"properties\":{\"code\":{\"description\":\"A declared code of this specification, such as `rooms/keys/read:hostRefused`, `rooms/keys/read:cannotOpen` or `rooms/keys/read:notAttempted`, or a standard code (SPEC §8.3).\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"details\":{\"description\":\"As that code defines its `details`.\",\"type\":\"object\"},\"message\":{\"description\":\"Human-readable. Not normative: a consumer acts on `code` and `details`, never on this.\",\"maxLength\":1024,\"type\":\"string\"},\"retryable\":{\"type\":\"boolean\"}},\"required\":[\"code\",\"retryable\"],\"title\":\"KeyError\",\"type\":\"object\"}"
    };
}
