macro_rules! d_MessageMeta_5001bf49 {
    () => {
        "\"MessageMeta\":{\"additionalProperties\":false,\"description\":\"Metadata of one stored message. Never carries the message body.\",\"properties\":{\"deliveredAt\":{\"description\":\"When the message was first handed to the recipient. Present only when deliveryState is `delivered`.\",\"format\":\"date-time\",\"type\":\"string\"},\"deliveryState\":{\"$ref\":\"#/$defs/DeliveryState\"},\"expiresAt\":{\"description\":\"When the mediator will expire the message if it is not deleted first.\",\"format\":\"date-time\",\"type\":\"string\"},\"from\":{\"$ref\":\"#/$defs/Vid\",\"description\":\"The sender, where the mediator knows it. Absent for anonymous messages.\"},\"msgId\":{\"description\":\"The mediator's identifier for the stored message; the handle messaging/message/get and messaging/message/delete accept.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"protocol\":{\"$ref\":\"#/$defs/WireProtocol\"},\"queue\":{\"$ref\":\"#/$defs/Queue\"},\"receivedAt\":{\"description\":\"When the mediator stored the message.\",\"format\":\"date-time\",\"type\":\"string\"},\"size\":{\"description\":\"Stored size in bytes.\",\"minimum\":0,\"type\":\"integer\"},\"to\":{\"$ref\":\"#/$defs/Vid\",\"description\":\"The recipient account.\"}},\"required\":[\"msgId\",\"queue\",\"size\",\"receivedAt\"],\"title\":\"MessageMeta\",\"type\":\"object\"}"
    };
}
