macro_rules! d_MessageState_e33b2396 {
    () => {
        "\"MessageState\":{\"description\":\"Where a sent message stands. `queued`: held for the recipient and not yet handed over. `delivered`: handed to the recipient (pickup or live stream) and not yet removed by it. `collected`: removed by the recipient — acknowledged after pickup, fetched with delete, or deleted or purged by it. `withdrawn`: removed by the sender. `discarded`: removed by the mediator before the recipient took it — expired, or its account was removed. `unknown`: the mediator holds neither the message nor a receipt for it under the requester.\",\"enum\":[\"queued\",\"delivered\",\"collected\",\"withdrawn\",\"discarded\",\"unknown\"],\"title\":\"MessageState\",\"type\":\"string\"}"
    };
}
