macro_rules! d_MonitorEvent_ed025cc7 {
    () => {
        "\"MonitorEvent\":{\"additionalProperties\":false,\"description\":\"One observed step in the life of one message at the mediator. Carries metadata only — never a message body.\",\"properties\":{\"channel\":{\"$ref\":\"#/$defs/TrafficChannel\"},\"direction\":{\"$ref\":\"#/$defs/TrafficDirection\"},\"from\":{\"$ref\":\"#/$defs/Vid\",\"description\":\"The sender, where the mediator knows it.\"},\"latencyMs\":{\"description\":\"For `delivered` and `forwarded`: milliseconds since the message was stored.\",\"minimum\":0,\"type\":\"integer\"},\"messageType\":{\"description\":\"The plaintext message type, present only when the mediator itself was the addressee and read it (a routing forward, a pickup request, a trust-task type URI, a trust ping). Absent for end-to-end-encrypted traffic the mediator only relays.\",\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"msgId\":{\"description\":\"The stored message's identifier, once it has one; correlates the events of one message and matches MessageMeta.msgId.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"occurredAt\":{\"description\":\"When the step happened, with sub-second precision where the mediator has it.\",\"format\":\"date-time\",\"type\":\"string\"},\"outcome\":{\"$ref\":\"#/$defs/TrafficOutcome\",\"description\":\"Present when stage is `refused`, and on any other stage that failed.\"},\"protocol\":{\"$ref\":\"#/$defs/WireProtocol\"},\"size\":{\"description\":\"Frame size in bytes.\",\"minimum\":0,\"type\":\"integer\"},\"stage\":{\"$ref\":\"#/$defs/TrafficStage\"},\"to\":{\"$ref\":\"#/$defs/Vid\",\"description\":\"The recipient, where the mediator knows it.\"}},\"required\":[\"occurredAt\",\"direction\",\"stage\",\"channel\",\"protocol\"],\"title\":\"MonitorEvent\",\"type\":\"object\"}"
    };
}
