macro_rules! d_MonitorFilter_707cb209 {
    () => {
        "\"MonitorFilter\":{\"additionalProperties\":false,\"description\":\"Selects which events a monitor subscription receives. Every member present narrows the selection (members are ANDed; values within one member are ORed). An empty filter selects everything the requester is entitled to see.\",\"properties\":{\"channels\":{\"items\":{\"$ref\":\"#/$defs/TrafficChannel\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"dids\":{\"description\":\"Only events whose `from` or `to` is one of these accounts.\",\"items\":{\"$ref\":\"#/$defs/Vid\"},\"maxItems\":100,\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"directions\":{\"items\":{\"$ref\":\"#/$defs/TrafficDirection\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"failuresOnly\":{\"description\":\"Only events that carry an `outcome`.\",\"type\":\"boolean\"},\"messageTypePrefixes\":{\"description\":\"Only events whose `messageType` starts with one of these strings. Events with no `messageType` never match when this member is present.\",\"items\":{\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"maxItems\":20,\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"protocols\":{\"items\":{\"$ref\":\"#/$defs/WireProtocol\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"stages\":{\"items\":{\"$ref\":\"#/$defs/TrafficStage\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true}},\"title\":\"MonitorFilter\",\"type\":\"object\"}"
    };
}
pub(crate) use d_MonitorFilter_707cb209;

