macro_rules! d_RightRecord_2a3590b0 {
    () => {
        "\"RightRecord\":{\"additionalProperties\":false,\"description\":\"One recorded right. Implied rights (§4.2 of the rights model: `own` implies `maintain` implies `commit.sign` on the same resource; `ns.admin` implies `repo.create` and `own` across its namespace) are not records and never appear as RightRecords. A record carrying `breakGlass` was given by its subject to themselves through git-ns/right/break-glass; it is a real right, published like any other, and is shown with that flag on every surface that shows the record.\",\"properties\":{\"breakGlass\":{\"$ref\":\"#/$defs/BreakGlass\",\"description\":\"Present exactly when the subject gave themselves this right through git-ns/right/break-glass. Absent for every other record.\"},\"expiresAt\":{\"description\":\"When the right lapses. Absent: no expiry.\",\"format\":\"date-time\",\"type\":\"string\"},\"grantedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"grantedBy\":{\"$ref\":\"#/$defs/Did\",\"description\":\"The actor whose task caused the right: the granter, the creator of a repository (for its first `own`), the adopting admin, the transferring owner, or the binding admin (for the first `git.ns.admin`). The VTC's own DID for a right it derives from its configuration.\"},\"reason\":{\"description\":\"The granter's free-text reason. Disclosed only to holders of `git.repo.own` on the resource and of `git.ns.admin` over it.\",\"maxLength\":1024,\"type\":\"string\"},\"resource\":{\"$ref\":\"#/$defs/Resource\"},\"right\":{\"$ref\":\"#/$defs/Right\"},\"subject\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who holds the right. For `git.commit.sign` this is the DID whose commit signatures the CI check accepts.\"}},\"required\":[\"subject\",\"right\",\"resource\",\"grantedBy\",\"grantedAt\"],\"title\":\"RightRecord\",\"type\":\"object\"}"
    };
}
pub(crate) use d_RightRecord_2a3590b0;

