macro_rules! d_Sensitivity_372f6ec0 {
    () => {
        "\"Sensitivity\":{\"description\":\"How carefully a value is shown TO ITS OWN HOLDER. `high` means a consumer masks it by default, reveals it one attribute at a time on a deliberate act, and — the half that is not cosmetic — omits it from a listing that did not ask for sensitive values.\\n\\nAbsent means *not decided by the holder*, not `normal`: a consumer resolves it from the claim-type registry (see CLAIM-TYPES.md §4), which is why this member is optional and why an unregistered token resolves conservatively rather than permissively.\\n\\nDistinct from how linkable the value is. A payment card is highly sensitive and barely linkable — every card number is unique, so knowing one tells a second verifier nothing about the first. Reading either as a proxy for the other produces a consumer that hides the wrong things.\",\"enum\":[\"normal\",\"high\"],\"title\":\"Sensitivity\",\"type\":\"string\"}"
    };
}
pub(crate) use d_Sensitivity_372f6ec0;

macro_rules! d_ServiceInstance_07d559e7 {
    () => {
        "\"ServiceInstance\":{\"additionalProperties\":false,\"properties\":{\"advertisedServices\":{\"description\":\"`service[].type` values of the instance's DID document when the control plane last resolved it. Display only: nothing is routed on it. Absent when the document has not been resolved.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\"},\"did\":{\"description\":\"The instance's own DID — the identity its signed documents are verified against and the one the control plane addresses.\",\"minLength\":1,\"type\":\"string\"},\"enabledMethods\":{\"description\":\"DID methods the instance can host (e.g. `webvh`, `web`, `webs`), as it declared at registration.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"instanceId\":{\"description\":\"Stable identifier the control plane uses for this instance. SHOULD be derived from the instance's DID so it survives restarts.\",\"minLength\":1,\"type\":\"string\"},\"label\":{\"description\":\"Operator-chosen display label. Untrusted free text.\",\"maxLength\":256,\"type\":\"string\"},\"lastHealthCheck\":{\"description\":\"When the instance last answered a health probe. Absent when it never has.\",\"format\":\"date-time\",\"type\":\"string\"},\"lastInbound\":{\"$ref\":\"#/$defs/TransportObservation\",\"description\":\"The last document the control plane received from this instance. Absent when it has received none.\"},\"lastOutbound\":{\"$ref\":\"#/$defs/TransportObservation\",\"description\":\"The last document the control plane delivered to this instance. Absent when it has delivered none.\"},\"publicUrl\":{\"description\":\"The instance's public base URL, where it serves DID resolution. Absent when the instance registered without one.\",\"format\":\"uri\",\"type\":\"string\"},\"registeredAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"servedDomains\":{\"description\":\"Hosting domains the instance has acknowledged serving. Always present — empty for an instance that serves none, which includes every `witness` and `watcher`.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\"},\"serviceType\":{\"description\":\"`server` — a hosting server (edge) that resolves DIDs the control plane syncs to it. `witness` — a did:webvh witness. `watcher` — a did:webvh watcher that mirrors logs.\",\"enum\":[\"server\",\"witness\",\"watcher\"],\"type\":\"string\"},\"servicesCheckedAt\":{\"description\":\"When `advertisedServices` was last resolved. Absent with it.\",\"format\":\"date-time\",\"type\":\"string\"},\"status\":{\"description\":\"The control plane's current verdict, from the instance's last answered health probe. `degraded` — answered late; `unreachable` — has not answered within the control plane's configured window.\",\"enum\":[\"active\",\"degraded\",\"unreachable\"],\"type\":\"string\"}},\"required\":[\"instanceId\",\"did\",\"serviceType\",\"status\",\"registeredAt\",\"servedDomains\"],\"title\":\"ServiceInstance\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ServiceInstance_07d559e7;

