macro_rules! d_WorldColour_5c5bfdd5 {
    () => {
        "\"WorldColour\":{\"description\":\"A colour **name**, resolved by each consumer against its own palette — never a hex value or any other literal. Two reasons, and both are about the consumer rather than the holder. A literal cannot be legible in a terminal, in a light theme and in a dark one at once, so a stored `#8B0000` is a colour that is wrong somewhere and the holder has no way to know where. And a consumer that reserves colours to mean something — an error, a warning, an irreversible act — must be able to keep a holder's decorative choice out of that channel; it cannot do that with an arbitrary value, and it can do it trivially with a closed set it maps itself. The eight members are chosen to be distinguishable from one another and deliberately carry no status connotation: none is named for success, warning or danger.\",\"enum\":[\"slate\",\"indigo\",\"teal\",\"moss\",\"sand\",\"clay\",\"rose\",\"plum\"],\"title\":\"WorldColour\",\"type\":\"string\"}"
    };
}
pub(crate) use d_WorldColour_5c5bfdd5;

macro_rules! d_WriteRelationship_2674584a {
    () => {
        "\"WriteRelationship\":{\"additionalProperties\":true,\"description\":\"A relationship to assert (HCP 4.2.3, 5.2.3). Only a `contradicts` relationship may carry a `proposal` (HCP 4.7.4); not checked by the schema. The provider assigns `assertedBy` and `recordedAt` (HCP 5.2.3).\",\"properties\":{\"proposal\":{\"$ref\":\"#/$defs/Proposal\",\"description\":\"A proposal for resolving the conflict, on a `contradicts` relationship only (HCP 4.7.4).\"},\"target\":{\"description\":\"The related entry: its `ref` for a Context Client, its `id` for a Management Client (HCP 5.2.3).\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"}},\"required\":[\"type\",\"target\"],\"type\":\"object\"}"
    };
}
pub(crate) use d_WriteRelationship_2674584a;

macro_rules! d_Write_1533e72a {
    () => {
        "\"Write\":{\"additionalProperties\":false,\"description\":\"One write within the batch. Shaped exactly like a vta/app-state/put payload minus the context and namespace, which the batch supplies.\",\"oneOf\":[{\"not\":{\"required\":[\"mergePatch\"]},\"required\":[\"value\"]},{\"not\":{\"required\":[\"value\"]},\"required\":[\"mergePatch\"]}],\"properties\":{\"expectedVersion\":{\"$ref\":\"#/$defs/ExpectedVersion\",\"description\":\"This write's own precondition, evaluated independently of every other write in the batch. A positive value requires the record to be at exactly that version; 0 requires that no live record exists.\"},\"key\":{\"$ref\":\"#/$defs/Key\"},\"mergePatch\":{\"description\":\"An RFC 7386 JSON Merge Patch applied to the record's current value. Requires a live record at the address; otherwise this write's outcome is `notFound`. Mutually exclusive with `value`.\",\"type\":\"object\"},\"value\":{\"description\":\"The complete new value, replacing whatever the record held. Any JSON value, including `null`. Mutually exclusive with `mergePatch`.\"}},\"required\":[\"key\"],\"title\":\"Write\",\"type\":\"object\"}"
    };
}
pub(crate) use d_Write_1533e72a;
